import { test } from "node:test";
import assert from "node:assert/strict";
import { longestConsecutive } from "./attempt.js";

const todo = longestConsecutive.toString().includes("TODO");
const skip =
  todo && "unsolved — edit attempt.js (delete the TODO line) to activate these tests";

test("classic example", { skip }, () => {
  assert.equal(longestConsecutive([100, 4, 200, 1, 3, 2]), 4);
});

test("empty array", { skip }, () => {
  assert.equal(longestConsecutive([]), 0);
});

test("single element", { skip }, () => {
  assert.equal(longestConsecutive([7]), 1);
});

test("duplicates count once", { skip }, () => {
  assert.equal(longestConsecutive([1, 1, 1]), 1);
  assert.equal(longestConsecutive([1, 2, 0, 1]), 3);
});

test("no two values adjacent", { skip }, () => {
  assert.equal(longestConsecutive([1, 3, 5]), 1);
});

test("negatives and zero", { skip }, () => {
  assert.equal(longestConsecutive([-3, -2, -1, 0]), 4);
});

test("run crossing zero", { skip }, () => {
  assert.equal(longestConsecutive([2, -1, 0, 1, -2]), 5);
});

test("two separate runs — the longer one wins", { skip }, () => {
  assert.equal(longestConsecutive([1, 2, 3, 10, 11]), 3);
  assert.equal(longestConsecutive([10, 11, 1, 2, 3]), 3);
});

test("already sorted input", { skip }, () => {
  assert.equal(longestConsecutive([1, 2, 3, 4, 5]), 5);
});

test("reverse sorted input", { skip }, () => {
  assert.equal(longestConsecutive([5, 4, 3, 2, 1]), 5);
});

test("the longest run appears last in the array", { skip }, () => {
  assert.equal(longestConsecutive([9, 1, 4, 7, 3, 2, 6, 5]), 7);
});

test("does not mutate or reorder the input", { skip }, () => {
  const nums = [100, 4, 200, 1, 3, 2];
  longestConsecutive(nums);
  assert.deepEqual(nums, [100, 4, 200, 1, 3, 2]);
});

test("large shuffled run of 1000", { skip }, () => {
  const nums = Array.from({ length: 1000 }, (_, k) => k);
  // deterministic shuffle so the test is reproducible
  for (let i = nums.length - 1; i > 0; i--) {
    const j = (i * 7919) % (i + 1);
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  assert.equal(longestConsecutive(nums), 1000);
});

test("many duplicates around a short run", { skip }, () => {
  const nums = [5, 5, 5, 5, 6, 5, 5, 7, 5];
  assert.equal(longestConsecutive(nums), 3);
});

/**
 * Length of the longest run of consecutive integers present in `nums`.
 * Values may appear in any order; duplicates count once.
 *
 * @param {number[]} nums - unsorted integers (may be empty, may repeat)
 * @returns {number} length of the longest consecutive value-run
 */
export function longestConsecutive(nums) {
  // A Set gives O(1) "is this value present?" and drops duplicates for
  // free — which is exactly the two things this problem needs.
  const values = new Set(nums);

  let longest = 0;

  for (const value of values) {
    // Only walk a run from its START. If value - 1 is present, this value
    // is in the middle of a run that some earlier (smaller) value will
    // handle — skip it. This guard is what keeps the whole thing linear.
    if (values.has(value - 1)) continue;

    // Walk upward as far as the run goes.
    let current = value;
    let length = 1;
    while (values.has(current + 1)) {
      current++;
      length++;
    }

    if (length > longest) longest = length;
  }

  // Empty input never enters the loop, so 0 falls out naturally.
  return longest;
}

